<script setup lang="ts">
import { computed, ref } from 'vue';
import { useWorkbench } from './workbench';
const host=location.host;
const w=useWorkbench();const filter=ref('');const topic=ref('sys.info');const data=ref('{}');const response=ref('');const elapsed=ref(0);const pending=ref(false);
const lines=computed(()=>(w.snapshot.value?.logs??[]).filter(l=>`${l.pluginId} ${l.message}`.toLowerCase().includes(filter.value.toLowerCase())).slice().reverse());
async function send(){pending.value=true;const start=performance.now();try{response.value=JSON.stringify(await w.call('device_request',{role:w.role.value,topic:topic.value,data:JSON.parse(data.value)}),null,2);}catch(e){response.value=JSON.stringify({error:e instanceof Error?e.message:String(e)},null,2);}finally{elapsed.value=Math.round(performance.now()-start);pending.value=false;}}
</script>
<template>
  <div class="page-content logs-layout"><section class="panel"><div class="panel-heading"><h2>运行日志</h2><span class="chip">最近 500 条</span></div><div class="log-filter"><input v-model="filter" placeholder="搜索插件 ID 或日志内容" aria-label="搜索日志"/></div><div class="log-stream"><div v-for="line in lines" :key="line.sequence" class="log-line" :class="{error:/error|failed|denied|deadline/i.test(line.message)}"><time>{{new Date(line.time).toLocaleTimeString('zh-CN',{hour12:false})}}</time><code>{{line.pluginId}}</code><span>{{line.message}}</span></div><p v-if="!lines.length" class="empty-copy">没有匹配的运行日志。</p></div></section><div class="stack"><section class="panel"><div class="panel-heading"><h2>NyaLink 请求调试</h2><span class="chip mono">{{elapsed}} ms</span></div><div class="form-body"><div class="form-grid"><label>Topic<input v-model="topic" list="topics"/><datalist id="topics"><option>sys.info</option><option>plugin.list</option><option>ui.tree</option><option>ui.event</option><option>eye.mode</option><option>access.members</option></datalist></label><label>测试身份<select v-model="w.role.value"><option value="owner">主人</option><option value="family">家人</option><option value="guest">访客</option></select></label></div><label>请求数据<textarea v-model="data" class="code-editor" rows="5" spellcheck="false"/></label><button class="primary" :disabled="pending" @click="send">{{pending?'请求中…':'发送请求'}}</button><pre v-if="response" class="response-code">{{response}}</pre></div></section><section class="panel"><div class="panel-heading"><h2>MCP 与完整状态</h2><span class="chip">{{w.snapshot.value?.tools.length}} 工具</span></div><div class="form-body"><code class="endpoint">http://{{host}}/mcp</code><p class="field-hint">Agent 使用 stdio 或带 Bearer 鉴权的 HTTP。工作台与 MCP 调用同一套操作。</p><details><summary>可用工具</summary><div class="tool-list"><code v-for="name in w.snapshot.value?.tools" :key="name">{{name}}</code></div></details><details><summary>查看全部模拟器状态</summary><pre class="response-code">{{JSON.stringify(w.snapshot.value,null,2)}}</pre></details></div></section></div></div>
</template>
